导入：
```ts
function pickFile(): void { fileInput.value?.click() }
async function onFileChange(event: Event): Promise<void> {
  const input = event.target as HTMLInputElement
  const file = input.files?.[0]
  input.value = ''
  if (!file) return
  importing.value = true
  try {
    const result = await skillsApi.importZip(file)
    if (result.warnings.length > 0) {
      ElMessage.warning(`导入成功，但有 ${result.warnings.length} 条警告：${result.warnings.join('；')}`)
    } else {
      ElMessage.success(`已导入技能「${result.skill.name}」`)
    }
    capabilities.invalidate()
    await load()
  } catch (cause) {
    ElMessage.error(cause instanceof Error ? cause.message : '导入失败')
  } finally {
    importing.value = false
  }
}
```

注意 `input.files?.[0]`：FileList 支持索引访问，noUncheckedIndexedAccess 会让 `input.files[0]` 是 `File | undefined`。用 `?.` 或 `?? undefined`。`input.files?.[0]` OK。

