```vue
<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import CapabilityGate from './CapabilityGate.vue'
import EmptyState from '@/components/common/EmptyState.vue'
import ErrorState from '@/components/common/ErrorState.vue'
import LoadingBlock from '@/components/common/LoadingBlock.vue'
import StatCard from '@/components/common/StatCard.vue'
import { memoriesApi } from '@/api/memories'
import { useSystemStore } from '@/stores/system'
import { MEMORY_KIND_LABELS, MEMORY_SOURCE_LABELS } from '@/types'
import { formatDateTime } from '@/utils/format'
import type { Memory, MemoryKind, MemoryStatus } from '@/types'

const system = useSystemStore()
const enabled = computed(() => system.enabled('memories'))

const items = ref<Memory[]>([])
const stats = ref<Record<string, number>>({})
const loading = ref(false)
const loadingMore = ref(false)
const error = ref<string | null>(null)
const loaded = ref(false)

const q = ref('')
const kindFilter = ref<'all' | MemoryKind>('all')
const statusFilter = ref<'all' | MemoryStatus>('all')
const nextCursor = ref<string | null>(null)
const hasMore = ref(false)

const total = computed(() => stats.value.total ?? items.value.length)
const activeCount = computed(() => stats.value.active ?? 0)
const archivedCount = computed(() => stats.value.archived ?? 0)

// 弹窗
const dialogOpen = ref(false)
const editingId = ref<string | null>(null)
const form = reactive({ kind: 'fact' as MemoryKind, title: '', content: '', pinned: false })
const savingMemory = ref(false)
const deletingId = ref<string | null>(null)
const clearing = ref(false)
const exporting = ref(false)

watch(enabled, (on) => {
  if (on && !loaded.value && !loading.value) void load()
}, { immediate: true })

let searchTimer: ReturnType<typeof setTimeout> | undefined

watch([q, kindFilter, statusFilter], () => {
  if (!loaded.value) return
  if (searchTimer) clearTimeout(searchTimer)
  searchTimer = setTimeout(() => { void load() }, 300)
})

async function load(): Promise<void> {
  loading.value = true
  error.value = null
  try {
    const page = await memoriesApi.list({
      q: q.value.trim() || undefined,
      kind: kindFilter.value === 'all' ? undefined : kindFilter.value,
      status: statusFilter.value === 'all' ? undefined : statusFilter.value,
      limit: 20,
    })
    items.value = page.items
    nextCursor.value = page.next_cursor
    hasMore.value = page.has_more
    stats.value = page.stats ?? {}
    loaded.value = true
  } catch (cause) {
    error.value = cause instanceof Error ? cause.message : '加载记忆失败'
  } finally {
    loading.value = false
  }
}

async function loadMore(): Promise<void> {
  if (loadingMore.value || !nextCursor.value) return
  loadingMore.value = true
  try {
    const page = await memoriesApi.list({
      q: q.value.trim() || undefined,
      kind: kindFilter.value === 'all' ? undefined : kindFilter.value,
      status: statusFilter.value === 'all' ? undefined : statusFilter.value,
      limit: 20,
      cursor: nextCursor.value,
    })
    items.value = [...items.value, ...page.items]
    nextCursor.value = page.next_cursor
    hasMore.value = page.has_more
    stats.value = page.stats ?? stats.value
  } catch (cause) {
    ElMessage.error(cause instanceof Error ? cause.message : '加载更多失败')
  } finally {
    loadingMore.value = false
  }
}
```

注意：`kind: kindFilter.value === 'all' ? undefined : kindFilter.value`，类型 MemoryKind | undefined。MemoryListParams.kind 是 MemoryKind（可选）。OK。

openCreate / openEdit：
```ts
function openCreate(): void {
  editingId.value = null
  form.kind = 'fact'
  form.title = ''
  form.content = ''
  form.pinned = false
  dialogOpen.value = true
}

function openEdit(memory: Memory): void {
  editingId.value = memory.id
  form.kind = memory.kind
  form.title = memory.title
  form.content = memory.content
  form.pinned = memory.pinned
  dialogOpen.value = true
}

async function submitMemory(): Promise<void> {
  if (savingMemory.value) return
  const title = form.title.trim()
  const content = form.content.trim()
  if (!title || !content) {
    ElMessage.warning('标题与内容不能为空')
    return
  }
  savingMemory.value = true
  try {
    if (editingId.value) {
      await memoriesApi.update(editingId.value, {
        kind: form.kind,
        title,
        content,
        pinned: form.pinned,
      })
    } else {
      await memoriesApi.create({ kind: form.kind, title, content, pinned: form.pinned })
    }
    dialogOpen.value = false
    await load()
    ElMessage.success(editingId.value ? '已更新记忆' : '已新增记忆')
  } catch (cause) {
    ElMessage.error(cause instanceof Error ? cause.message : '保存失败')
  } finally {
    savingMemory.value = false
  }
}
```

注意：editingId 在 submit 后 load 会 reset，但先 `dialogOpen.value = false` 再 load。success 消息用 editingId 判断，但 editingId 还没重置（load 不重置 editingId）。但我在 try 里先判断。问题：`await load()` 后 editingId 仍是旧值，`ElMessage.success(editingId.value ? ...)` 正确。但注意我用了 `editingId.value` 在闭包里，load 不会改它。OK。但更清晰：先存 `const isEdit = editingId.value !== null`。我用这个更稳。

删除：
```ts
async function removeMemory(memory: Memory): Promise<void> {
  try {
    await ElMessageBox.confirm(
      `将删除「${memory.title}」，该操作不可撤销。`,
      '删除记忆？',
      { type: 'warning', confirmButtonText: '删除', cancelButtonText: '取消' },
    )
  } catch { return }
  deletingId.value = memory.id
  try {
    await memoriesApi.remove(memory.id)
    items.value = items.value.filter((item) => item.id !== memory.id)
    stats.value = { ...stats.value, total: Math.max(0, (stats.value.total ?? 0) - 1) }
    // 也可 reload。但 reload 更一致。用 reload 简化。
    ElMessage.success('已删除')
    await load()
  } catch (cause) {
    ElMessage.error(cause instanceof Error ? cause.message : '删除失败')
  } finally {
    deletingId.value = null
  }
}
```
其实删除后直接 reload 即可（保持 stats 一致）。我删掉手动改 stats，直接 await load()。

