        <div class="dialog-actions">
          <button type="button" class="btn" @click="editOpen = false">取消</button>
          <button type="submit" class="btn primary" :disabled="editing">
            {{ editing ? '保存中…' : '保存' }}
          </button>
        </div>
      </form>
    </el-dialog>
  </section>
</template>

