                class="btn"
                :disabled="!system.a2a?.jsonrpc_url"
                @click="copy(system.a2a?.jsonrpc_url ?? '')"
              >
                复制 JSON-RPC
              </button>
            </div>
          </section>
        </template>

        <template v-else>
          <section class="card">
            <header class="card-head">
              <h2>关于</h2>
            </header>
            <dl class="kv">
              <div>
                <dt>版本</dt>
                <dd class="mono">{{ system.info?.version ?? '0.1.0' }}</dd>
              </div>
              <div>
                <dt>构建</dt>
                <dd class="mono">{{ system.info?.build ?? '—' }}</dd>
              </div>
              <div>
                <dt>环境</dt>
